import{_ as r,I as t,o,c as l,b6 as a,j as d,J as s,w as p}from"./chunks/framework.BUXTSoD9.js";const P=JSON.parse(`{"title":"Développement pratique d'une SaaS de génération d'images IA moderne","description":"","frontmatter":{},"headers":[],"relativePath":"fr-fr/stage-2/assignments/modern-landing-page/index.md","filePath":"fr-fr/stage-2/assignments/modern-landing-page/index.md"}`),c={name:"fr-fr/stage-2/assignments/modern-landing-page/index.md"},u={style:{margin:"32px 0"}};function m(h,e,g,b,f,v){const i=t("StepBar"),n=t("ClientOnly");return o(),l("div",null,[e[0]||(e[0]=a('<h1 id="developpement-pratique-d-une-saas-de-generation-d-images-ia-moderne" tabindex="-1">Développement pratique d&#39;une SaaS de génération d&#39;images IA moderne <a class="header-anchor" href="#developpement-pratique-d-une-saas-de-generation-d-images-ia-moderne" aria-label="Permalink to “Développement pratique d&#39;une SaaS de génération d&#39;images IA moderne”">​</a></h1><h2 id="apercu" tabindex="-1">Aperçu <a class="header-anchor" href="#apercu" aria-label="Permalink to “Aperçu”">​</a></h2><p>Ce projet pratique vous demande de réaliser, à partir d&#39;un véritable PRD (document d&#39;exigences produit), une SaaS de génération d&#39;images IA inspirée de l&#39;expérience Midjourney. Vous passerez par l&#39;ensemble du processus : analyse des besoins, décomposition du projet, développement itératif et mise en ligne.</p><p>Il s&#39;agit du projet pratique synthétique de l&#39;Étape 2. Dans les chapitres précédents, vous avez appris séparément la conception de pages frontend, le développement d&#39;API backend, les opérations sur les bases de données et l&#39;intégration de paiements. Ce projet vous demande de tout assembler pour livrer un prototype de produit fonctionnel.</p><h2 id="prerequis" tabindex="-1">Prérequis <a class="header-anchor" href="#prerequis" aria-label="Permalink to “Prérequis”">​</a></h2><p>Avant de commencer ce projet, vous devriez maîtriser les éléments suivants :</p><ul><li>Conception de pages frontales et utilisation de bibliothèques de composants (<a href="./../../frontend/ui-design/">Conception UI</a>, <a href="./../../frontend/modern-component-library/">Bibliothèque de composants moderne</a>)</li><li>Conception et développement d&#39;API backend (<a href="./../../backend/ai-interface-code/">Écriture de code d&#39;interface</a>)</li><li>Bases de données et Supabase (<a href="./../../backend/database-supabase/">Des bases de données à Supabase</a>)</li><li>Intégration de paiements (<a href="./../../backend/stripe-payment/">Système de paiement Stripe</a>)</li><li>Flux de travail Git et déploiement (<a href="./../../backend/git-workflow/">Git et GitHub</a>, <a href="./../../backend/zeabur-deployment/">Déployer une application web</a>)</li></ul><h2 id="objectifs-d-apprentissage" tabindex="-1">Objectifs d&#39;apprentissage <a class="header-anchor" href="#objectifs-d-apprentissage" aria-label="Permalink to “Objectifs d&#39;apprentissage”">​</a></h2><p>Après avoir terminé ce projet, vous serez capable de :</p><ol><li>Lire et comprendre un véritable PRD et en extraire une liste de tâches de développement</li><li>Décomposer les modules à partir du PRD et établir un plan de progression par étapes</li><li>Utiliser l&#39;IA pour vous aider à construire le squelette frontend et développer les API backend</li><li>Valider et optimiser de manière itérative chaque module</li><li>Effectuer des tests de bout en bout et faire passer le projet du stade « fonctionnel » à « livrable »</li></ol><h2 id="presentation-du-projet" tabindex="-1">Présentation du projet <a class="header-anchor" href="#presentation-du-projet" aria-label="Permalink to “Présentation du projet”">​</a></h2><p>Le produit que vous allez construire est une plateforme SaaS de génération d&#39;images IA moderne, comprenant trois sous-systèmes :</p><table tabindex="0"><thead><tr><th>Sous-système</th><th>Responsabilité</th></tr></thead><tbody><tr><td><strong>Site vitrine</strong></td><td>Présentation du produit, tarification, FAQ, conversion des inscriptions</td></tr><tr><td><strong>Espace de travail utilisateur</strong></td><td>Saisie de prompts, génération d&#39;images, galerie, crédits, forfaits, interactions communautaires</td></tr><tr><td><strong>Back-office administrateur</strong></td><td>Gestion des utilisateurs, des tâches, des paiements, modération du contenu, indicateurs SaaS, surveillance système</td></tr></tbody></table><p>Le backend doit prendre en charge les capacités principales suivantes : authentification des utilisateurs, tâches de génération d&#39;images, stockage objet OSS, paiement par crédits et forfaits, interactions sociales autour des images et surveillance des données opérationnelles.</p><div class="tip custom-block"><p class="custom-block-title">Accès au PRD</p><p>Le document d&#39;exigences de ce projet se trouve sur GitHub : <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/fr-fr/stage-2/assignments/modern-landing-page/PRD.md" target="_blank" rel="noreferrer">Voir le PRD</a></p></div>',15)),d("div",u,[s(n,null,{default:p(()=>[s(i,{active:0,items:[{title:"Analyse des besoins",description:"Lire le PRD, extraire les pages, modules, modèles de données et limites"},{title:"Construction du squelette",description:"Générer avec l'IA trois squelettes frontend (www / app / admin)"},{title:"Développement itératif",description:"Compléter module par module : API, permissions, paiement, surveillance"},{title:"Tests et mise en ligne",description:"Tests de bout en bout, déploiement et préparation de la démonstration"}]})]),_:1})]),e[1]||(e[1]=a(`<h2 id="partie-1-analyse-des-besoins" tabindex="-1">Partie 1 : Analyse des besoins <a class="header-anchor" href="#partie-1-analyse-des-besoins" aria-label="Permalink to “Partie 1 : Analyse des besoins”">​</a></h2><h3 id="_1-1-lire-le-prd" tabindex="-1">1.1 Lire le PRD <a class="header-anchor" href="#_1-1-lire-le-prd" aria-label="Permalink to “1.1 Lire le PRD”">​</a></h3><p>Ouvrez le document PRD et répondez aux questions suivantes :</p><ul><li>Combien le système a-t-il de points d&#39;accès ? Quelles pages chaque point couvre-t-il ?</li><li>Quelle est la fonctionnalité principale de chaque page ?</li><li>Quels modules et tables de données le backend comprend-il ?</li><li>Quelle est la portée du MVP ? Que fait-on dans la première version, que laisse-t-on de côté ?</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>Si les questions ci-dessus n&#39;ont pas de réponse claire, ne commencez pas à coder. Une mauvaise compréhension des besoins est la cause la plus fréquente de retour en arrière.</p></div><h3 id="_1-2-confirmer-l-architecture-du-systeme" tabindex="-1">1.2 Confirmer l&#39;architecture du système <a class="header-anchor" href="#_1-2-confirmer-l-architecture-du-systeme" aria-label="Permalink to “1.2 Confirmer l&#39;architecture du système”">​</a></h3><p>À partir de la description du PRD, dégagez l&#39;architecture globale du système :</p><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; web[&quot;Site vitrine&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd --&gt; app[&quot;Espace de travail utilisateur&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd --&gt; admin[&quot;Back-office administrateur&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; auth[&quot;Authentification&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; gen[&quot;Tâches de génération d&#39;images&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gen --&gt; oss[&quot;Stockage objet OSS&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gen --&gt; db[&quot;Base de données&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  billing[&quot;Paiement et forfaits&quot;] --&gt; db</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  social[&quot;Partage / Likes / Commentaires / Reposts&quot;] --&gt; db</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin --&gt; analytics[&quot;Tableau de bord des indicateurs SaaS&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin --&gt; observability[&quot;Surveillance API / DB / Provider&quot;]</span></span></code></pre></div><p>Il est recommandé de redessiner le diagramme d&#39;architecture vous-même pour confirmer que votre compréhension du système est complète.</p><h2 id="partie-2-construction-du-squelette-du-projet" tabindex="-1">Partie 2 : Construction du squelette du projet <a class="header-anchor" href="#partie-2-construction-du-squelette-du-projet" aria-label="Permalink to “Partie 2 : Construction du squelette du projet”">​</a></h2><h3 id="_2-1-generer-les-pages-frontales" tabindex="-1">2.1 Générer les pages frontales <a class="header-anchor" href="#_2-1-generer-les-pages-frontales" aria-label="Permalink to “2.1 Générer les pages frontales”">​</a></h3><p>Utilisez l&#39;IA pour générer d&#39;abord la structure de base et les données fictives de toutes les pages. L&#39;objectif de cette étape est de mettre en place l&#39;architecture de l&#39;information et le routage, sans connexion à une API réelle.</p><p>Prompt de référence :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Veuillez générer, sur la base du PRD actuel, le squelette frontend d&#39;une SaaS de génération d&#39;images IA moderne.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Exigences :</span></span>
<span class="line"><span>1. Divisé en trois points d&#39;accès : www, app, admin</span></span>
<span class="line"><span>2. Le site vitrine comprend : page d&#39;accueil, tarification, FAQ</span></span>
<span class="line"><span>3. L&#39;app comprend : connexion, inscription, espace de génération, galerie, forfaits, crédits, communauté, détails des œuvres, profil utilisateur</span></span>
<span class="line"><span>4. L&#39;admin comprend : accueil du back-office, gestion des utilisateurs, gestion des tâches, gestion du contenu, gestion des forfaits, commandes de paiement, configuration opérationnelle, indicateurs SaaS, surveillance système</span></span>
<span class="line"><span>5. Générer d&#39;abord uniquement la structure des pages et des données fictives, sans connexion à une API réelle</span></span>
<span class="line"><span>6. Style inspiré de Midjourney : épuré, moderne, avec une sensation produit</span></span></code></pre></div><h3 id="_2-2-verifier-la-structure-des-pages" tabindex="-1">2.2 Vérifier la structure des pages <a class="header-anchor" href="#_2-2-verifier-la-structure-des-pages" aria-label="Permalink to “2.2 Vérifier la structure des pages”">​</a></h3><p>Après la génération du squelette, vérifiez point par point :</p><ul><li>[ ] Les routes des trois points d&#39;accès sont-elles indépendantes (<code>/</code>, <code>/app</code>, <code>/admin</code>) ?</li><li>[ ] Le nombre de pages correspond-il au PRD ?</li><li>[ ] Chaque page est-elle accessible et navigable normalement ?</li><li>[ ] Les données fictives montrent-elles les états UI de base (listes, états vides, formulaires, etc.) ?</li></ul><h2 id="partie-3-developpement-iteratif" tabindex="-1">Partie 3 : Développement itératif <a class="header-anchor" href="#partie-3-developpement-iteratif" aria-label="Permalink to “Partie 3 : Développement itératif”">​</a></h2><h3 id="_3-1-progresser-par-module" tabindex="-1">3.1 Progresser par module <a class="header-anchor" href="#_3-1-progresser-par-module" aria-label="Permalink to “3.1 Progresser par module”">​</a></h3><p>Sur la base du squelette, complétez les fonctionnalités module par module dans l&#39;ordre suivant :</p><ol><li><strong>Authentification</strong> : Inscription, connexion, distinction des rôles</li><li><strong>Base de données</strong> : Création des tables de données, API de lecture/écriture</li><li><strong>Cœur du métier</strong> : Tâches de génération d&#39;images, stockage des résultats</li><li><strong>Stockage OSS</strong> : Upload et accès aux images</li><li><strong>Paiement</strong> : Forfaits, crédits, intégration Stripe</li><li><strong>Interactions sociales</strong> : Partage, likes, commentaires</li><li><strong>Back-office</strong> : Gestion des utilisateurs, des tâches, modération du contenu</li><li><strong>Surveillance des données</strong> : Tableau de bord des indicateurs SaaS, surveillance système</li></ol><p>Après chaque module terminé, effectuez une auto-vérification à l&#39;aide du tableau suivant :</p><table tabindex="0"><thead><tr><th>Point de contrôle</th><th>Méthode de vérification</th></tr></thead><tbody><tr><td>Cohérence des pages</td><td>Le nombre de pages, les points d&#39;accès et les fonctionnalités correspondent-ils au PRD ?</td></tr><tr><td>Exactitude des API</td><td>Les paramètres de requête, la structure de retour et la gestion des statuts sont-ils raisonnables ?</td></tr><tr><td>Isolation des permissions</td><td>Les utilisateurs normaux et les administrateurs sont-ils correctement isolés ?</td></tr><tr><td>Cohérence des données</td><td>La base de données, le stockage OSS, les paiements et les crédits sont-ils cohérents ?</td></tr><tr><td>Démontrabilité</td><td>Pouvez-vous démontrer un flux métier complet à quelqu&#39;un ?</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>Si vous constatez que le contenu généré par l&#39;IA s&#39;écarte du PRD, ne repartez pas de zéro pour toute la page. Demandez-lui simplement de modifier le module spécifique concerné.</p></div><h3 id="_3-2-roles-et-responsabilites" tabindex="-1">3.2 Rôles et responsabilités <a class="header-anchor" href="#_3-2-roles-et-responsabilites" aria-label="Permalink to “3.2 Rôles et responsabilités”">​</a></h3><p>Au cours du développement itératif, vous devez jouer trois rôles simultanément :</p><ul><li><strong>Chef de produit</strong> : Confirmer que les fonctionnalités de chaque module correspondent au PRD</li><li><strong>Responsable technique</strong> : Confirmer que la solution d&#39;implémentation est raisonnable</li><li><strong>Ingénieur de test</strong> : Confirmer que les fonctionnalités fonctionnent correctement</li></ul><h2 id="partie-4-tests-et-mise-en-ligne" tabindex="-1">Partie 4 : Tests et mise en ligne <a class="header-anchor" href="#partie-4-tests-et-mise-en-ligne" aria-label="Permalink to “Partie 4 : Tests et mise en ligne”">​</a></h2><h3 id="_4-1-tests-de-bout-en-bout" tabindex="-1">4.1 Tests de bout en bout <a class="header-anchor" href="#_4-1-tests-de-bout-en-bout" aria-label="Permalink to “4.1 Tests de bout en bout”">​</a></h3><p>L&#39;accent dans la phase finale n&#39;est pas sur l&#39;ajout de nouvelles pages, mais sur la validation complète des flux métier. Vérifiez au minimum les scénarios suivants :</p><ul><li>Inscription -&gt; Achat de crédits -&gt; Génération d&#39;images -&gt; Consultation de l&#39;historique -&gt; Interactions sociales</li><li>Connexion administrateur -&gt; Consultation des données utilisateurs -&gt; Consultation des statistiques de tâches -&gt; Consultation de la surveillance système</li></ul><h3 id="_4-2-deploiement" tabindex="-1">4.2 Déploiement <a class="header-anchor" href="#_4-2-deploiement" aria-label="Permalink to “4.2 Déploiement”">​</a></h3><p>Déployez le projet dans un environnement public et assurez-vous que :</p><ul><li>Les variables d&#39;environnement sont entièrement configurées</li><li>L&#39;URL de callback de connexion est correcte</li><li>L&#39;URL de callback de paiement est correcte</li><li>Aucune page ne présente d&#39;états de chargement, vides ou d&#39;erreurs manquants</li></ul><p>Tutoriel de déploiement : <a href="./../../backend/git-workflow/">Flux de travail Git et GitHub</a>, <a href="./../../backend/zeabur-deployment/">Comment déployer une application web</a>.</p><h2 id="livrables" tabindex="-1">Livrables <a class="header-anchor" href="#livrables" aria-label="Permalink to “Livrables”">​</a></h2><p>Après avoir terminé ce projet, vous devez soumettre les éléments suivants :</p><ul><li>[ ] Un lien de démonstration en ligne accessible</li><li>[ ] Un lien vers le dépôt de code source (avec README)</li><li>[ ] Le document PRD</li><li>[ ] Des captures d&#39;écran des pages principales (accueil du site vitrine, espace de génération, galerie, page des forfaits, accueil du back-office)</li><li>[ ] Une vidéo de démonstration de 60 secondes (couvrant : inscription -&gt; génération -&gt; consultation -&gt; back-office admin)</li></ul><p>Le README doit contenir au minimum : la présentation du projet, la description des pages principales, la stack technique, les étapes de démarrage local et la liste des variables d&#39;environnement.</p><h2 id="criteres-d-evaluation" tabindex="-1">Critères d&#39;évaluation <a class="header-anchor" href="#criteres-d-evaluation" aria-label="Permalink to “Critères d&#39;évaluation”">​</a></h2><table tabindex="0"><thead><tr><th>Dimension</th><th>Exigences de base</th><th>Exigences avancées</th></tr></thead><tbody><tr><td>Alignement PRD</td><td>Pages, fonctionnalités et structures de données globalement conformes au PRD</td><td>Chaque décision de design peut être clairement reliée au PRD</td></tr><tr><td>Boucle produit</td><td>Inscription -&gt; Achat de crédits -&gt; Génération d&#39;images -&gt; Historique -&gt; Interactions sociales fonctionne</td><td>État des paiements, solde des crédits et nombre de générations sont cohérents</td></tr><tr><td>Capacités du back-office</td><td>Gestion des utilisateurs, des tâches, des paiements et du contenu est visible</td><td>Le tableau de bord des indicateurs SaaS et la page de surveillance système sont complets et fonctionnels</td></tr><tr><td>Complétude technique</td><td>Frontend, backend, base de données, OSS et chaîne de paiement sont connectés</td><td>Gestion des erreurs, états vides et états de chargement sont présents</td></tr><tr><td>Qualité de livraison</td><td>Peut être déployé et exécuté</td><td>README clair, vidéo de démonstration bien structurée</td></tr></tbody></table><h2 id="references" tabindex="-1">Références <a class="header-anchor" href="#references" aria-label="Permalink to “Références”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">Conception UI</a></li><li><a href="./../../frontend/multi-product-ui/">Concevoir des pages et des boutons en référençant les guidelines UI</a></li><li><a href="./../../frontend/llm-skills-beautiful/">Rendre les interfaces attrayantes avec les LLM et les Skills</a></li><li><a href="./../../frontend/design-to-code/">Du prototype de design au code de projet</a></li><li><a href="./../../frontend/modern-component-library/">Mettre à jour votre interface avec une bibliothèque de composants moderne</a></li><li><a href="./../../backend/database-supabase/">Des bases de données à Supabase</a></li><li><a href="./../../backend/ai-interface-code/">Écriture de code d&#39;interface assistée par IA</a></li><li><a href="./../../backend/git-workflow/">Flux de travail Git et GitHub</a></li><li><a href="./../../backend/zeabur-deployment/">Comment déployer une application web</a></li><li><a href="./../../backend/stripe-payment/">Comment intégrer Stripe et d&#39;autres systèmes de paiement</a></li></ul>`,43))])}const q=r(c,[["render",m]]);export{P as __pageData,q as default};
